"""Build static PLAIN SIGHT pages. No runtime framework or network build dependency."""
from pathlib import Path
import json, html
from PIL import Image
ROOT = Path(__file__).resolve().parents[1]
DATA = json.loads((ROOT/'src/collection.json').read_text())
BY_ID = {x['id']:x for s in DATA for x in [s,*s['crops']]}
SERIES = [('gestures','01','Gestures','People / posture / fabric'),('arrangements','02','Arrangements','Objects / texture / balance'),('in-between','03','In Between','Space / geometry / light')]
e = lambda x: html.escape(str(x),quote=True)
def photo(id, eager=False, cls='', sizes='(max-width: 760px) 90vw, 50vw'):
    x=BY_ID[id]
    return f'<img class="{cls}" src="assets/images/{id}.webp" srcset="assets/thumbs/{id}.webp 480w, assets/images/{id}.webp {x["width"]}w" sizes="{sizes}" width="{x["width"]}" height="{x["height"]}" alt="{e(x["alt"])}" {"fetchpriority=high" if eager else "loading=lazy"} decoding="async">'
def look(id, content, cls='', label=None):
    return f'<a class="{cls}" href="light-table.html?source={id}" data-look="{id}"'+(f' aria-label="{e(label)}"' if label else '')+'>'+content+'</a>'
def caption(a,b):return f'<figcaption class="image-caption"><span>{a}</span><span>{b}</span></figcaption>'
def frame(id, cls='large-figure', eager=False):
    x=BY_ID[id];return f'<figure class="{cls}">{look(id,photo(id,eager),label="Look closely at "+x["title"])}{caption("SOURCE "+x["number"],x["title"])}</figure>'
def nav(page):
    entries=[('index','Studies'),('light-table','Light table'),('publication','Publication'),('studio','Studio'),('contact','Contact')]
    current='index' if page in ['index','gestures','arrangements','in-between'] else page
    links=''.join(f'<a href="{key}.html'+('#work' if key=='index' else '')+'"'+(' aria-current="page"' if current==key else '')+f'>{label}</a>' for key,label in entries)
    return f'<header class="topbar shell"><a class="brand" href="index.html" aria-label="PLAIN SIGHT home"><i class="brand-symbol" aria-hidden="true"></i><span>PLAIN<br>SIGHT</span></a><button class="nav-toggle" type="button" aria-controls="site-nav" aria-expanded="false" data-nav-toggle>Menu +</button><nav class="primary-nav" id="site-nav" aria-label="Primary">{links}</nav><span class="edition">OBSERVATION EDITION / 03</span></header>'
def footer():return '''<footer class="footer shell"><div class="footer-top"><div><p class="eyebrow">THE ORDINARY, OBSERVED DIFFERENTLY.</p><h2>A little more<br><em>attention.</em></h2></div><div><p>A self-directed image-making studio concept by Jocelyn Martinez. Five AI-generated source scenes, eleven editorial crops, and a study of how framing changes what we notice.</p><a class="text-link" href="contact.html">Contact the designer <span aria-hidden="true">↗</span></a></div></div><div class="footer-bottom"><nav class="footer-links" aria-label="Further reading"><a href="case-study.html">Case study</a><a href="publication.html#campaign">Campaign artwork</a><a href="motion.html">Motion study</a><a href="email.html">Email specimen</a><a href="../index.html">Jocelyn’s portfolio ↗</a></nav><span>CONCEPT PROJECT · 2026</span></div><div class="footer-wordmark" aria-hidden="true">PLAIN SIGHT</div></footer>'''
def dialog():return '''<dialog class="look-dialog" id="look-dialog" aria-labelledby="viewer-title"><div class="viewer-head"><p>PLAIN SIGHT / FOCUSED VIEW</p><button class="viewer-close" data-close-viewer autofocus>Close <span aria-hidden="true">×</span></button></div><div class="viewer-body"><div><img class="viewer-image" id="viewer-image" alt=""><p id="viewer-error" class="load-error" hidden>The image could not load. <a id="viewer-direct" href="assets/images/gesture-seated.webp">Open the source image directly</a>.</p></div><div class="viewer-info"><p class="eyebrow" id="viewer-series"></p><h2 id="viewer-title"></h2><p id="viewer-note"></p><a id="viewer-inspect" class="text-link" href="light-table.html">Inspect the framing <span aria-hidden="true">↗</span></a></div></div><div class="viewer-footer"><span class="viewer-status" id="viewer-status" role="status"></span><p class="fine">Use ← / → to move · Esc to close</p><div class="actions"><button class="button" data-viewer-prev aria-label="Previous source image">← Previous</button><button class="button" data-viewer-next aria-label="Next source image">Next →</button></div></div></dialog>'''
def page(name,title,body,description,extra_data=None):
    payload=json.dumps(DATA,ensure_ascii=False).replace('</','<\\/')
    ext=f'<script id="publication-data" type="application/json">{json.dumps(extra_data,ensure_ascii=False).replace("</","<\\/")}</script>' if extra_data else ''
    text=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f2efe8"><title>{e(title)} — PLAIN SIGHT</title><meta name="description" content="{e(description)}"><link rel="icon" href="assets/mark.svg" type="image/svg+xml"><link rel="preload" href="assets/fonts/dm-sans.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="assets/styles.css"><script src="assets/model.js" defer></script><script src="assets/app.js" defer></script></head>
<body data-page="{name}"><a class="skip" href="#main">Skip to content</a>{nav(name)}<main id="main" tabindex="-1">{body}</main>{footer()}{dialog()}<script id="collection-data" type="application/json">{payload}</script>{ext}</body></html>'''
    (ROOT/f'{name}.html').write_text(text)
def heading(label,title,copy,extra=''):
    return f'<header class="page-heading shell"><div><p class="eyebrow">{label}</p><h1>{title}</h1></div><div class="intro"><p class="body-large">{copy}</p>{extra}</div></header>'
def study_nav(current):return '<nav class="chapter-nav" aria-label="Photographic studies"><a href="index.html#work">← All studies</a>'+''.join(f'<a href="{s}.html"'+(' aria-current="page"' if current==s else '')+f'><span>{n}</span> {name}</a>' for s,n,name,_ in SERIES)+'</nav>'
def card(s):return f'<article class="source-card" data-source-card="{s["id"]}" data-series="{s["series"]}">{look(s["id"],photo(s["id"],sizes="(max-width: 400px) 90vw, (max-width: 760px) 45vw, 28vw")+"<span class=open-hint>Look closely ↗</span>","source-picture", "Look closely at "+s["title"])}<div class="source-meta"><span>Source {s["number"]} / {s["seriesName"]}</span><span>{len(s["crops"])} crop studies</span></div><h3>{s["title"]}</h3><a class="text-link" href="light-table.html?source={s["id"]}">Inspect the framing <span aria-hidden="true">↗</span></a></article>'
def build():
    thumb=ROOT/'assets/thumbs';thumb.mkdir(exist_ok=True)
    for x in BY_ID.values():
        im=Image.open(ROOT/f'assets/images/{x["id"]}.webp');im.resize((480,round(480*x['height']/x['width'])),Image.Resampling.LANCZOS).save(thumb/f'{x["id"]}.webp','WEBP',quality=78,method=6)
    study_links=''.join(f'<a class="study-link" href="{s}.html"><span><strong>{name} ↗</strong><small>{theme}</small></span><span class="chapter-number">{n}</span></a>' for s,n,name,theme in SERIES)
    filters=''.join(f'<a href="index.html?series={s}#work" data-filter="{s}" aria-current="{str(s=="all").lower()}">{name}</a>' for s,name in [('all','All five'),('gestures','People'),('arrangements','Objects'),('in-between','Spaces')])
    home=f'''<section class="hero shell" aria-labelledby="hero-title"><div class="hero-topline eyebrow"><span>PLAIN SIGHT / INDEPENDENT IMAGE STUDIES</span><span>FIVE SOURCES. THREE WAYS OF SEEING.</span></div><div class="hero-grid"><div class="hero-copy"><h1 id="hero-title">A <em>second</em><br>look.</h1><p class="body-large">The ordinary, observed differently. An exhibition of people, objects and the spaces in between.</p><div class="actions"><a class="button primary" href="#work">Explore the studies <span aria-hidden="true">↓</span></a>{look('gesture-seated','Enter focused view ↗','text-link')}</div></div><div class="hero-visual"><figure>{look('gesture-seated',photo('gesture-seated',True),'hero-image','Look closely at A posture, a pause')}{caption('01 / GESTURES','A posture, a pause')}</figure><div class="hero-under"><p>Nothing added.<br>Something <em>noticed.</em></p><a class="hero-detail" href="light-table.html?source=gesture-seated&amp;crop=gesture-seated-space">{photo('gesture-seated-space',sizes='160px')}<span>The same image. <b>↗</b></span></a></div></div></div><div class="hero-foot"><span class="folio">OBSERVE → REFRAME → READ</span><span class="fine">AI-generated source imagery. Original editorial decisions.</span></div></section>
+<section id="work" class="section shell"><div class="section-head"><div><p class="eyebrow">01 / THE OBSERVATION INDEX</p><h2>Five sources.<br><em>Three studies.</em></h2></div><p>Start with a subject. Follow a frame. Each source keeps its identity as it moves from exhibition to crop study to publication.</p></div><div class="study-links">{study_links}</div><div class="index-tools"><nav class="filter-list" aria-label="Filter source images">{filters}</nav><span class="source-count" id="source-count" role="status">5 original sources</span></div><div class="source-grid" id="source-grid">{''.join(card(s) for s in DATA)}</div></section>
+<section class="method-band section"><div class="shell method-layout"><div class="method-copy"><p class="eyebrow">02 / THE LIGHT TABLE</p><h2>Same image.<br><em>Another reading.</em></h2><p>A frame is a decision. Compare a source with its actual editorial crops and read what each edit brings forward—and leaves behind.</p><a class="button" href="light-table.html?source=arrangement-bloom">Open the light table <span aria-hidden="true">↗</span></a></div><div class="method-pair"><figure>{photo('arrangement-bloom')}{caption('SOURCE 03','The whole arrangement')}</figure><figure>{photo('arrangement-bloom-base')}{caption('DERIVED CROP','Weight, glass, linen')}</figure></div></div></section>
+<section class="section shell book-teaser"><a class="book-pages" href="publication.html?page=12#reader" aria-label="Read the actual publication, starting at page 12"><img src="assets/publication/page-12.webp" width="707" height="1000" loading="lazy" alt="Actual publication page 12: the original flower composition"><img src="assets/publication/page-13.webp" width="707" height="1000" loading="lazy" alt="Actual publication page 13: related flower crops and editing notes"></a><div><p class="eyebrow">03 / THE READING EDITION</p><h2>Attention,<br><em>in 24 pages.</em></h2><p>The same five sources, a different pace. Chapter openings, source images, crop decisions and room to pause.</p><div class="actions"><a class="button" href="publication.html">Read the publication ↗</a><a class="text-link" href="case-study.html">Behind the decisions ↗</a></div></div></section>'''.replace('\n+','\n')
    page('index','The ordinary, observed differently',home,'A photographic exhibition and source-aware light table. Five generated scenes, three studies, one practice of attention.')
    for s,n,name,theme in SERIES:
        ids=[x['id'] for x in DATA if x['series']==s]
        if s=='gestures':
            title='Gestures';intro='A body, a fold, a pause. Two human scenes, observed from different distances.'
            content=f'''<div class="chapter-opening">{frame(ids[0],eager=True)}<aside><span class="number-display">01</span><h2>Presence needs<br><em>a little space.</em></h2><p>The figure occupies one side of the frame. The wall gives her posture somewhere to settle.</p><a class="text-link" href="light-table.html?source=gesture-seated">Explore this source ↗</a></aside></div><section class="chapter-section gesture-pair"><figure class="portrait">{look(ids[1],photo(ids[1]),label='Look closely at The weight of a fold')}{caption('SOURCE 02','The weight of a fold')}</figure><div><p class="eyebrow">FROM POSTURE TO MATERIAL</p><h2>The movement<br>is in <em>the cloth.</em></h2><p class="body-large">The full portrait connects the turned head and lifted hands. A closer edit lets light and fabric become the subject.</p><figure class="detail">{photo('gesture-fabric-fabric')}{caption('DERIVED FROM SOURCE 02','The material edit')}</figure><a class="text-link" href="light-table.html?source=gesture-fabric&amp;crop=gesture-fabric-fabric">Compare this crop with its source ↗</a></div></section>'''
            next_s='arrangements';next_name='Arrangements';pub=5
        elif s=='arrangements':
            title='Arrange<br><em>ments.</em>';intro='A stem, a surface, a counterweight. Two still lifes organized by the relationships between ordinary things.'
            content=f'''<div class="chapter-opening arrangement-opening">{frame(ids[0],eager=True)}<aside><span class="number-display">02</span><h2>A small<br><em>conversation.</em></h2><p>One dark flower, one clear glass. The stem connects them; linen and stone keep the balance slightly off-centre.</p><a class="text-link" href="light-table.html?source=arrangement-bloom">Inspect the balance ↗</a></aside></div><section class="chapter-section arrangement-grid"><div><p class="eyebrow">SOURCE 04 / OBJECTS IN CONVERSATION</p><h2>Weight.<br><em>And counterweight.</em></h2><p class="body-large">The heavy vase anchors the left. A branch carries that weight across the image, toward the glass and the light.</p>{frame(ids[1])}</div><figure class="object-detail">{photo('arrangement-table-light')}{caption('DERIVED FROM SOURCE 04','The lighter edit')}<a class="text-link" href="light-table.html?source=arrangement-table&amp;crop=arrangement-table-light">What changes when the vase leaves? ↗</a></figure></section>'''
            next_s='in-between';next_name='In Between';pub=11
        else:
            title='In<br><em>Between.</em>';intro='An opening, an empty chair, a crossing of light. One room is enough for several readings.'
            content=f'''<div class="chapter-opening space-opening">{frame(ids[0],eager=True)}<aside><span class="number-display">03</span><h2>Almost nothing.<br><em>And enough.</em></h2><p>Three geometries hold the room: a tall opening, the chair’s edges and the sloping light. The empty space connects them.</p><a class="text-link" href="light-table.html?source=between-room">Inspect this room ↗</a></aside></div><section class="chapter-section space-sequence"><div class="space-copy"><p class="eyebrow">ONE SOURCE / THREE DERIVATIVES</p><h2>A threshold.<br>A trace.<br><em>A pause.</em></h2><p>These are different edits of the same generated room. Moving the frame changes what provides its sense of scale.</p><a class="text-link" href="light-table.html?source=between-room&amp;crop=between-room-window">Follow the framing ↗</a></div><figure>{photo('between-room-window')}{caption('SOURCE 05 / WINDOW CROP','An opening')}</figure><figure>{photo('between-room-chair')}{caption('SOURCE 05 / CHAIR CROP','A trace of presence')}</figure></section>'''
            next_s='gestures';next_name='Gestures';pub=17
        body=heading(f'STUDY {n} / {theme}',title,intro)+f'<div class="shell">{study_nav(s)}{content}<div class="chapter-close"><div><p class="eyebrow">KEEP LOOKING</p><h2>From the frame<br><em>to the page.</em></h2><p class="fine">{len(ids)} original generated scene{ "s" if len(ids)>1 else "" }; the related edits are labelled as crops.</p><a class="text-link" href="publication.html?page={pub}#reader">Read this chapter in the publication ↗</a></div><a class="next-study" href="{next_s}.html">Next study<br>{next_name} ↗</a></div></div>'
        page(s,f'{name} / Study {n}',body,intro)
    first=DATA[0];crop=first['crops'][0]
    rail=''.join(f'<a class="source-choice" href="light-table.html?source={x["id"]}" data-select-source="{x["id"]}" aria-current="{str(i==0).lower()}" aria-label="Inspect source {x["number"]}: {e(x["title"])}">{photo(x["id"],sizes="90px")}<span><small>{x["number"]}<span class="source-choice-series"> / {x["seriesName"]}</span></small><span class="source-choice-title">{x["title"]}</span></span></a>' for i,x in enumerate(DATA))
    def panel(kind,x):
        is_source=kind=='source';return f'<figure class="compare-panel"><div class="compare-label"><span>{"Original source" if is_source else "Editorial crop"}</span><span id="{kind}-identity">SOURCE 01'+('' if is_source else ' / CROP 01')+f'</span></div><div class="image-mat"><div class="inspection-frame" id="{kind}-frame" style="--image-width:{min(500,360*x["width"]/x["height"]):.0f}px">'+photo(x['id'],eager=True)+f'<span class="composition-guides" data-guides hidden aria-hidden="true"></span></div></div><figcaption id="{kind}-caption">{e(x["alt"])}</figcaption></figure>'
    fallback=''.join(f'<article><h3>{x["number"]} / {x["title"]}</h3><p>{x["note"]}</p><p><a href="assets/images/{x["id"]}.webp">Open original image</a></p>'+''.join(f'<p><a href="assets/images/{c["id"]}.webp">{c["title"]}</a>: {c["note"]}</p>' for c in x['crops'])+'</article>' for x in DATA)
    table=f'''<section class="table-heading shell"><p class="eyebrow">THE VISUAL LIGHT TABLE</p><h1>One source. <em>Several readings.</em></h1><div class="heading-row"><p>Choose an original, then an edit. Notice what becomes the subject when something else leaves the frame.</p><p class="fine">Five AI-generated sources. Eleven existing crops.<br>New editorial notes; no shoot or camera data.</p></div></section><div class="shell" id="light-table"><nav class="source-rail" aria-label="Choose original source">{rail}</nav><noscript><p class="fallback-note">The interactive comparison needs JavaScript. All originals, crops and their notes remain available below.</p><div class="no-js-archive prose">{fallback}</div></noscript><div class="table-toolbar"><div><label class="field-label" for="crop-select">Compare the original with</label><select id="crop-select">{''.join(f'<option value="{c["id"]}">{c["title"]}</option>' for c in first['crops'])}</select></div><label class="checkbox"><input type="checkbox" id="guide-toggle"> Show rule-of-thirds guides</label></div><p class="sr-only" id="table-status" role="status"></p><div class="compare-stage">{panel('source',first)}{panel('crop',crop)}</div><p class="fine" style="margin-top:16px">Both images are shown in full. Display sizes differ; guides are an optional composition aid. These controls do not edit or save an image.</p><div class="reading-notes"><article><p class="eyebrow" id="source-meta">SOURCE 01 / GESTURES</p><h2 id="source-title">{first['title']}</h2><p id="source-note">{first['note']}</p><div class="actions"><a class="text-link" id="table-look" href="light-table.html?look=gesture-seated" data-look="gesture-seated">Open focused view ↗</a><a class="text-link" id="table-study" href="gestures.html">Return to Gestures ↗</a></div></article><article><p class="eyebrow">THE FRAMING DECISION</p><h2 id="crop-title">{crop['title']}</h2><p id="crop-note">{crop['note']}</p><a class="text-link" id="crop-publication" href="publication.html?page=7#reader">See this decision in the publication ↗</a></article></div><p class="load-error" id="table-error" hidden>An image could not load. <a href="index.html#work">Return to the collection</a> or follow its source link above.</p></div>'''
    page('light-table','The visual light table',table,'Compare original generated image sources with their real derivative crops, composition guides and authored editing notes.')
    pages=json.loads((ROOT/'src/publication-pages.json').read_text()) if (ROOT/'src/publication-pages.json').exists() else []
    if pages:
        p=pages[0]
        options=''.join(f'<option value="{x["page"]}">{x["page"]:02d} / {e(x["title"])}</option>' for x in pages)
        thumbs=''.join(f'<a href="assets/publication/page-{x["page"]:02d}.webp" data-page-link="{x["page"]}" aria-current="{str(x["page"]==1).lower()}"><img src="assets/publication/thumb-{x["page"]:02d}.webp" width="212" height="300" loading="lazy" alt="Page {x["page"]}: {e(x["description"])}"><small>{x["page"]:02d} / {e(x["title"])}</small></a>' for x in pages)
        posters=''.join(f'<figure><a href="assets/posters/poster-{i:02d}.svg"><img src="assets/posters/poster-{i:02d}.svg" width="840" height="1150" loading="lazy" alt="Editable PLAIN SIGHT campaign poster {i}"></a><figcaption>POSTER {i:02d} / Editable SVG master</figcaption></figure>' for i in range(1,7))
        assets=''.join(f'<a href="assets/social/social-{i:02d}.svg">Social composition {i:02d} ↗</a>' for i in range(1,7))
        pub=heading('STUDIES 01–03 / THE OBSERVATION EDITION','A slower<br><em>reading.</em>','Twenty-four actual pages. The same source images, with a deliberate change of scale and pace.','<p class="fine">A4 portrait · digital review edition · generated imagery<br>Not a press-certified file or a physical print run.</p>')+f'''<section class="shell" id="reader" aria-label="Publication reader"><nav class="chapter-nav" aria-label="Publication chapters"><a href="#page-index">All 24 pages ↓</a><a href="downloads/PLAIN_SIGHT_Studies_01-03.pdf#page=5" data-page-link="5">01 Gestures</a><a href="downloads/PLAIN_SIGHT_Studies_01-03.pdf#page=11" data-page-link="11">02 Arrangements</a><a href="downloads/PLAIN_SIGHT_Studies_01-03.pdf#page=17" data-page-link="17">03 In Between</a></nav><div class="reader-controls"><div class="actions"><button class="button" data-page-prev disabled>← Previous page</button><button class="button" data-page-next>Next page →</button></div><div><label class="sr-only" for="page-select">Choose publication page</label><select id="page-select">{options}</select></div><button class="button" id="page-zoom" aria-pressed="false">Enlarge page</button></div><div class="reader-layout"><div class="page-mat" id="page-mat" tabindex="0" role="region" aria-label="Publication page image; scroll when enlarged"><img id="publication-image" src="assets/publication/page-01.webp" width="707" height="1000" alt="{e(p['description'])}"><p class="load-error" id="publication-error" hidden>This preview could not load. <a href="downloads/PLAIN_SIGHT_Studies_01-03.pdf">Open the complete PDF</a>.</p></div><aside class="reader-aside"><p class="eyebrow" id="page-position" role="status">PAGE 01 / 24</p><h2 id="page-title">{e(p['title'])}</h2><p id="page-description">{e(p['description'])}</p><a class="text-link" id="page-source" href="light-table.html">Inspect the source images ↗</a><details><summary>Page text and image description</summary><p id="page-transcript">{e(p['text'])}</p></details><div class="actions"><a class="button primary" href="downloads/PLAIN_SIGHT_Studies_01-03.pdf" download>Download all 24 pages ↓</a></div><p class="fine" style="margin-top:20px">The preview is rendered from the linked PDF. Enlarge for a closer look; the text companion stays readable at any screen size.</p></aside></div><noscript><p class="fallback-note">Without JavaScript, use the complete page index below or download the PDF. Each thumbnail links to a readable full page through the image link in its caption.</p></noscript></section><section class="section shell" id="page-index"><div class="section-head"><div><p class="eyebrow">THE ENTIRE EDITION</p><h2>Every page,<br><em>in order.</em></h2></div><p>Enter at any point. The page number in the address remembers your place.</p></div><div class="publication-thumbs">{thumbs}</div><noscript><div class="asset-links">{''.join(f'<a href="assets/publication/page-{x["page"]:02d}.webp">Open full page {x["page"]}</a>' for x in pages)}</div></noscript></section><section class="section shell" id="campaign"><div class="section-head"><div><p class="eyebrow">THE IDENTITY OUTSIDE THE READER</p><h2>Type holds<br><em>its ground.</em></h2></div><p>Six retained campaign compositions. Editable vector type and shapes, with embedded raster imagery. Concept artworks, not installed campaigns.</p></div><div class="campaign-grid">{posters}</div><div class="asset-links">{assets}<a href="assets/stationery/business-cards.svg">Business cards ↗</a><a href="assets/stationery/letterhead.svg">Letterhead ↗</a><a href="assets/stationery/publication-sleeve.svg">Publication sleeve ↗</a><a href="email.html">Email specimen ↗</a><a href="docs/PRINT_SPECS.md">Print specifications ↗</a><a href="downloads/PLAIN_SIGHT_Identity_and_Production_Guide.pdf">Previous-edition identity guide ↗</a><a href="downloads/archive/PLAIN_SIGHT_Studies_Edition02.pdf">Previous publication edition ↗</a></div></section>'''
        page('publication','The 24-page publication',pub,'Read all 24 actual publication pages, inspect their source images and download the complete PLAIN SIGHT editorial edition.',pages)
    studio=heading('ABOUT / A SELF-DIRECTED STUDIO CONCEPT','Attention<br><em>is a medium.</em>','PLAIN SIGHT asks what changes when we look at the same thing twice.')+f'''<section class="shell"><div class="method-pair"><figure>{photo('gesture-fabric')}{caption('SOURCE 02','The full composition')}</figure><figure>{photo('gesture-fabric-fabric')}{caption('DERIVATIVE OF SOURCE 02','A material reading')}</figure></div><div class="note-grid section"><article><p class="eyebrow">01 / OBSERVE</p><h3>Begin with what is there.</h3><p>Five generated scenes provide the complete image library: two human compositions, two still lifes and one architectural interior.</p></article><article><p class="eyebrow">02 / REFRAME</p><h3>Make the decision visible.</h3><p>Eleven existing crops are linked to their actual parents. The new notes describe visible composition choices, not invented production history.</p></article><article><p class="eyebrow">03 / READ</p><h3>Change the pace.</h3><p>The publication moves between whole sources, close readings and editorial pauses. It shares the website’s vocabulary and image identities.</p></article></div></section><section class="section shell editorial-columns rule"><p class="eyebrow">CREATOR &amp; PROVENANCE</p><div class="prose"><h2>Jocelyn Martinez.</h2><p>A self-directed portfolio project combining visual identity, editorial art direction, interface design and frontend implementation.</p><p>PLAIN SIGHT is a fictional studio. All five photographic source scenes were generated with AI for this concept. No commissioned photographer, models, clients, physical sets or real photographic shoot are implied. The eleven derivatives are crops of those sources.</p><p>The framing notes in this edition were authored during reconstruction from the visible image material. No new interviews or usability study were conducted. The case study separates implementation checks from future research.</p><div class="actions"><a class="button" href="case-study.html">Read the case study ↗</a><a class="text-link" href="contact.html">Contact Jocelyn ↗</a></div></div></section>'''
    page('studio','The studio approach',studio,'The concept, creator, image provenance and editorial method behind PLAIN SIGHT.')
    contact=heading('CONTACT / THE DESIGNER BEHIND PLAIN SIGHT','A conversation<br><em>starts here.</em>','For real design inquiries, contact Jocelyn Martinez directly.')+'''<section class="shell section" style="padding-top:0"><div class="contact-block"><p class="eyebrow">JOCELYN MARTINEZ / DESIGN INQUIRIES</p><a class="contact-address" href="mailto:jocelyn.wisteria@gmail.com">jocelyn.wisteria@gmail.com ↗</a><p>This opens your email app. You can also copy the address and use your preferred email service.</p><div class="actions" style="margin-top:24px"><a class="button primary" href="mailto:jocelyn.wisteria@gmail.com?subject=Design%20inquiry%20%E2%80%94%20PLAIN%20SIGHT">Write an email ↗</a><button class="button" data-copy-email hidden>Copy email address</button></div><p class="copy-status" id="copy-status" role="status"></p><p class="fine">PLAIN SIGHT is a fictional studio identity. This website does not collect inquiries, create subscriptions or send messages.</p></div></section>'''
    page('contact','Contact Jocelyn Martinez',contact,'Contact the real designer behind the PLAIN SIGHT studio concept.')
    motion=heading('OPTIONAL / MOTION SPECIMEN','A measured<br><em>change.</em>','A small typographic study. Essential images and navigation never wait for an animation.')+'''<section class="shell"><div class="motion-specimen" id="motion-scene"><p class="eyebrow" style="color:inherit">TYPOGRAPHIC STUDY / MANUAL START</p><div class="motion-type" aria-hidden="true">LOOK<br><em>AGAIN.</em></div><p class="sr-only">Look again.</p><button class="button" id="motion-toggle" aria-pressed="false">Play motion</button><p id="motion-status" class="fine" role="status" style="margin-top:20px;color:inherit">Motion is paused.</p></div></section>'''
    page('motion','Typography in motion',motion,'An optional, reduced-motion-aware typographic experiment.')
    email=heading('DIGITAL APPLICATION / EMAIL SPECIMEN','An invitation<br><em>to look.</em>','A visual email composition, presented as a web specimen. It is not a subscription flow or an email-client compatibility test.')+f'''<section class="shell section" style="padding-top:0"><article class="email-specimen"><p class="eyebrow">PLAIN SIGHT / STUDIES 01–03</p><h2>The ordinary,<br><em>observed differently.</em></h2>{photo('arrangement-bloom-base')}<p>People, objects, rooms. Five source images and a new way of looking at what they contain.</p><a class="button primary" href="index.html#work">Explore the studies ↗</a><p class="fine">Self-directed studio concept by Jocelyn Martinez. AI-generated source imagery. No messages were sent.</p></article></section>'''
    page('email','Email design specimen',email,'A responsive announcement design for the PLAIN SIGHT observation edition.')
    build_case()
def build_case():
    before='docs/reconstruction/before/plain-sight-before-home.jpg';after='assets/reconstruction/home-desktop.jpg'
    case=heading('CASE STUDY / VISUAL IDENTITY × INTERACTION DESIGN','Make looking<br><em>the interaction.</em>','How can a digital exhibition encourage a second look without making the first one difficult?')+'''<div class="shell"><dl class="case-summary"><div><dt>Context</dt><dd>Self-directed concept · 2026</dd></div><div><dt>Work shown</dt><dd>Art direction, editorial, interaction and implementation</dd></div><div><dt>Evidence boundary</dt><dd>Source audit and functional checks; no user study or business outcomes</dd></div></dl><nav class="case-nav" aria-label="Case study sections"><a href="#challenge">The challenge</a><a href="#direction">Direction</a><a href="#architecture">Experience</a><a href="#system">System</a><a href="#publication">Publication</a><a href="#validation">Validation</a></nav></div>'''+f'''<section class="section shell" id="challenge"><div class="section-head"><div><p class="eyebrow">01 / THE CREATIVE QUESTION</p><h2>An exhibition.<br><em>With a way in.</em></h2></div><p>The original had a strong image world and real graphic artifacts. Its interface did little to explain the relationship between source, crop and editorial decision.</p></div><div class="evidence-pair"><figure><img src="{before}" width="1348" height="926" loading="lazy" alt="Original PLAIN SIGHT homepage, captured before reconstruction"><figcaption>BEFORE / Original live interface, preserved before editing.</figcaption></figure><figure><img src="{after}" width="1348" height="926" loading="lazy" alt="Reconstructed PLAIN SIGHT homepage, captured from the working website"><figcaption>AFTER / Actual reconstructed interface.</figcaption></figure></div><div class="note-grid"><article><h3>Confused image lineage</h3><p>Generic crop labels mixed originals and derivatives. Five source records now retain their identity across all views.</p></article><article><h3>Broken progression</h3><p>The old next-study route looped from Arrangements to Gestures. Explicit chapter navigation now includes all three studies.</p></article><article><h3>Publication without pages</h3><p>The old page previews were raw photographs. The reader now displays actual rendered pages from the linked PDF.</p></article></div></section><section class="section shell editorial-columns rule" id="direction"><p class="eyebrow">02 / RESEARCH &amp; ALTERNATIVES</p><div class="prose"><h2>Choose the structure.<br><em>Then the expression.</em></h2><p>Three directions were considered: a sequential Digital Exhibition, a fast Observation Index and a page-led Living Publication. The index offered the clearest connection between five sources and eleven derivatives. Exhibition pacing became an optional focused view; the publication retained its own reading rhythm.</p><p>Vignelli’s Unigrid informed shared structural alignment. Irma Boom’s book work informed sequence and changes of scale. Magnum Contact Sheets informed the visibility of editing decisions. Norman’s discoverability principles constrained the controls. These are transferable principles, not layouts copied from those works.</p><p>The research ledger contains 28 credited sources, with access and evidence limits. Pinterest pages were inaccessible; no unseen moodboard is claimed.</p><div class="actions"><a class="text-link" href="docs/reconstruction/concepts.html">Compare the three directions ↗</a><a class="text-link" href="docs/reconstruction/references.md">Read the influence matrix ↗</a></div></div></section><section class="section shell" id="architecture"><div class="section-head"><div><p class="eyebrow">03 / THE EXPERIENCE ARCHITECTURE</p><h2>Overview.<br>Focus.<br><em>Understanding.</em></h2></div><p>These are tasks, not three competing navigation systems. Every stage has an ordinary link back to the collection.</p></div><div class="note-grid"><article><p class="eyebrow">DISCOVER</p><h3>Three studies. Five sources.</h3><p>Visitors can enter a subject immediately or use the image index. Filtering updates the URL and the visible count.</p><a class="text-link" href="index.html#work">Try the index ↗</a></article><article><p class="eyebrow">LOOK</p><h3>One image at a time.</h3><p>A manual viewer shows the entire source image, position, previous/next controls and a clear exit. Escape returns focus to the starting control.</p>{look('gesture-fabric','Try focused viewing ↗','text-link')}</article><article><p class="eyebrow">UNDERSTAND</p><h3>The edit stays accountable.</h3><p>The light table pairs one original with its actual crop. Text explains the gain and the tradeoff. There is no drag-only control or invented camera metadata.</p><a class="text-link" href="light-table.html?source=gesture-fabric">Try the light table ↗</a></article></div><div class="evidence-pair"><figure><img src="assets/reconstruction/light-table-desktop.jpg" width="1348" height="926" loading="lazy" alt="Actual desktop light table with the original image and an editorial crop"><figcaption>WORKING COMPARISON / Source and derivative remain explicit.</figcaption></figure><figure><img src="assets/reconstruction/mobile-study.jpg" width="390" height="844" loading="lazy" alt="Actual narrow-width Gestures study with readable type and visible chapter navigation"><figcaption>RESPONSIVE STUDY / Distinct composition, shared controls.</figcaption></figure></div></section><section class="section shell editorial-columns rule" id="system"><p class="eyebrow">04 / THE SYSTEM</p><div class="prose"><h2>Two voices.<br><em>Clear responsibilities.</em></h2><p>Bodoni Moda provides the editorial display voice. DM Sans handles body text, captions, navigation and controls. The previous overlapping four-family system and second override stylesheet are removed. Fonts are served locally.</p><div class="type-sample"><p class="eyebrow">DISPLAY / BODONI MODA</p><p class="display">A second <em>look.</em></p><p style="margin-top:24px">TEXT &amp; CONTROLS / DM Sans<br>Original source · Compare the framing · Page 07 of 24</p></div><div class="token-strip">{''.join(f'<div><div class="swatch" style="background:{v}"></div><p>{k}<br><code>{v}</code></p></div>' for k,v in [('Paper','#f2efe8'),('Ink','#282824'),('Annotation','#723e43'),('Focus','#115b8b')])}</div><p>A twelve-column conceptual grid becomes explicit named layouts: intimate portrait relationships for Gestures, balanced object pairs for Arrangements, and generous spatial intervals for In Between. Mobile uses normal vertical flow; meaningful work is never hidden to fit.</p><p>Controls have visible focus, text labels and practical touch areas. Motion is brief feedback or an optional specimen. The primary content remains visible with reduced motion and without JavaScript.</p><a class="text-link" href="docs/reconstruction/system.md">Read the component and state rules ↗</a></div></section><section class="section shell editorial-columns rule" id="publication"><p class="eyebrow">05 / FROM SOURCE TO PUBLICATION</p><div class="prose"><h2>The same material.<br><em>A different pace.</em></h2><p>The 24-page edition was inspected page by page. The reconstruction repairs the obscured IN BETWEEN title, replaces ambiguous frame numbering with source/crop identities and develops a more deliberate progression through context, detail and reflection.</p><p>Actual PDF renders power the online reader. A page index, chapter jumps, enlargement, text companion and stable page URLs support both quick inspection and sustained reading. The PDF remains a digital review specimen, not a certified print-production file.</p><div class="actions"><a class="button" href="publication.html">Read the complete edition ↗</a><a class="text-link" href="docs/reconstruction/editorial-audit.md">See the page-by-page decisions ↗</a></div></div></section><section class="section shell editorial-columns rule" id="validation"><p class="eyebrow">06 / IMPLEMENTATION &amp; VALIDATION</p><div class="prose"><h2>Make the claim<br><em>inspectable.</em></h2><p>Static HTML carries the content. A small shared data model keeps sources, crops, chapter links and publication destinations aligned. JavaScript adds focused viewing, comparison, history-aware navigation and reading controls. There is no account, backend or saved personal collection.</p><p>Verification covers asset paths, source relationships, URL-state boundaries, chapter navigation and the actual browser journeys. The QA record states the commands, widths and interactions checked, with screenshots and remaining limits.</p><p>No interviewed participants, measured business outcomes or accessibility certification are claimed. Browser checks are implementation evidence, not proof that visitors understand the experience.</p><div class="actions"><a class="button" href="docs/reconstruction/qa.md">Read the verification record ↗</a><a class="text-link" href="docs/reconstruction/assessment.md">Critical review &amp; rubric ↗</a></div><h3>What should be tested next</h3><p>Ask a first-time viewer to identify which images are original and which are crops, then find the corresponding publication page. Observe whether the light table clarifies that relationship without explanation. Follow with screen-reader and physical-device sessions before claiming broader accessibility or usability results.</p></div></section>'''
    page('case-study','From exhibition to observation',case,'An evidence-led reconstruction of PLAIN SIGHT: source-aware exploration, editorial identity, real publication pages and tested interface behavior.')
if __name__=='__main__':build()
